  const n=v=>Number(v)||0;const mercadoUrl=raw=>{try{const url=new URL(raw),host=url.hostname.toLowerCase();return url.protocol==="https:"&&(host==="mercadolivre.com.br"||host.endsWith(".mercadolivre.com.br"))?url.href:"#";}catch{return "#";}};
