  const state={client:null,user:null,role:'personal_only',personalEditing:null,view:'inicio',recoveryMode:false,diagnosticIssues:[],loadErrors:[],data:{business_profiles:null,products:[],suppliers:[],purchases:[],purchase_items:[],sales:[],sale_items:[],stock_movements:[],inventory_summary:[],expenses:[],financial_transactions:[],marketplace_fees:[],marketing_campaigns:[],personal_transactions:[],personal_installments:[],personal_category_budgets:[],personal_recurring_bills:[],personal_savings_goals:[],market_price_reviews:[]},editing:null,search:'',sales30:{}};
  let toastTimer,loadSequence=0;
  function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600);}
  const diagnosticKey='meunegocio:diagnostics:v1';
  function safeDiagnosticText(value){return String(value||'').replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,'[e-mail oculto]').replace(/\b[0-9a-f]{8}-[0-9a-f-]{27,}\b/gi,'[id oculto]').replace(/\beyJ[A-Za-z0-9._-]+/g,'[token oculto]').replace(/Bearer\s+\S+/gi,'Bearer [token oculto]').slice(0,320);}
