    vendas:{title:'Vendas',eyebrow:'PEDIDOS E RECEBIMENTOS',subtitle:'Acompanhe pedidos, taxas e valores líquidos.',table:'sales',add:'new-sale',addLabel:'＋ Registrar venda',heading:'Histórico de vendas',hint:'O estoque baixa e o custo fica registrado pelo custo médio.',cols:[['item_summary','Pedido / produto'],['channel','Canal'],['sale_date','Data'],['gross_amount','Bruto'],['marketplace_fee','Taxas'],['net_amount','Líquido'],['payment_status','Recebimento']],fields:[['product_id','Produto','product',true],['quantity','Quantidade','number',true],['unit_price','Preço por unidade (R$)','number',true],['discount','Desconto (R$)','number'],['channel','Canal','select',[['shopee','Shopee'],['mercado_livre','Mercado Livre'],['direct','Direta'],['other','Outro']]],['external_order_id','Nº do pedido','text'],['sale_date','Data da venda','date'],['marketplace_fee','Taxas da plataforma (R$)','number'],['shipping_cost','Frete pago pelo vendedor (R$)','number'],['other_costs','Outros custos (R$)','number'],['payment_status','Recebimento','select',[['pending','Pendente'],['paid','Recebido']]],['notes','Observações','textarea']]},
