  async function handleSession(session){state.user=session?.user||null;$('authScreen').hidden=!!state.user;$('appShell').hidden=!state.user;if(!state.user){state.role='personal_only';return;}const access=await state.client.from('app_user_roles').select('role').eq('user_id',state.user.id).maybeSingle();state.role=access.data?.role==='admin'?'admin':'personal_only';if(access.error){state.roleError=true;showNotice('Acesso limitado: não foi possível consultar o perfil no Supabase. Aplique supabase/enable-personal-access.sql no SQL Editor do projeto e tente entrar novamente.');}else state.roleError=false;const fullName=state.user.user_metadata?.full_name||state.user.user_metadata?.name||'';$('avatar').textContent=fullName?fullName.trim().split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase():(state.user.email||'MN').slice(0,2).toUpperCase();$('today').textContent=new Intl.DateTimeFormat('pt-BR',{weekday:'short',day:'2-digit',month:'short'}).format(new Date());document.querySelectorAll('.nav-item[data-view]').forEach(button=>button.hidden=state.role!=='admin'&&button.dataset.view!=='pessoal');const privacyText=document.querySelector('.privacy p');if(privacyText)privacyText.textContent=state.role==='admin'?'Administrador: visualização de todas as contas.':'Acesso restrito aos seus gastos pessoais.';if(state.role==='admin')await ensureProfile();await loadAll();showView(state.role==='admin'?state.view:'pessoal');}
