  async function deletePersonalRecord(type,id){const table=type==='installment'?'personal_installments':type==='budget'?'personal_category_budgets':type==='goal'?'personal_savings_goals':type==='recurring'?'personal_recurring_bills':'personal_transactions',row=state.data[table].find(x=>x.id===id);if(!row||row.user_id!==state.user.id){toast('Você só pode excluir seus próprios registros.');return;}const label=type==='installment'||type==='goal'||type==='recurring'?row.title:type==='budget'?'o limite de '+row.category+' para '+String(row.month_start).slice(0,7):row.description;if(!confirm('Excluir '+label+'? Esta exclusão não pode ser desfeita.'))return;const r=await state.client.from(table).delete().eq('id',id).eq('user_id',state.user.id);if(r.error){toast(r.error.message);return;}await loadAll();toast(type==='budget'?'Limite excluído.':type==='goal'?'Meta excluída.':type==='recurring'?'Conta recorrente excluída.':'Registro excluído.');}
