  async function recordRecurringBill(id){const bill=state.data.personal_recurring_bills.find(x=>x.id===id);if(!bill||bill.user_id!==state.user.id||!bill.active){toast('Não foi possível registrar esta conta recorrente.');return;}const due=bill.next_due_date,paymentMethod=normalizePaymentMethod(bill.payment_method),entry={user_id:state.user.id,recurring_bill_id:bill.id,recurring_due_date:due,transaction_type:'expense',description:bill.title,category:bill.category,amount:bill.amount,transaction_date:due,payment_method:paymentMethod,status:paymentMethod==='credit_card'?'pending':'completed'};const saved=await state.client.from('personal_transactions').upsert(entry,{onConflict:'recurring_bill_id,recurring_due_date',ignoreDuplicates:true});if(saved.error){toast(saved.error.message);return;}const next=await state.client.from('personal_recurring_bills').update({next_due_date:nextRecurringDate(due,bill.frequency)}).eq('id',bill.id).eq('user_id',state.user.id);if(next.error){toast('Pagamento registrado; tente novamente para atualizar o próximo vencimento.');return;}await loadAll();toast('Pagamento registrado e próximo vencimento atualizado.');}
