  function renderSummary(name){const cards=[];if(name==='produtos')cards.push(['Produtos',state.data.products.length],['Unidades disponíveis',state.data.products.reduce((s,x)=>s+n(x.stock),0)],['Estoque a custo',money(state.data.products.reduce((s,x)=>s+n(x.stock)*n(x.purchase_cost),0))]);if(name==='compras')cards.push(['Compras',state.data.purchases.length],['Total comprado',money(state.data.purchases.reduce((s,x)=>s+n(x.total),0))],['A pagar',money(state.data.financial_transactions.filter(x=>x.source==='purchase'&&x.status==='pending').reduce((s,x)=>s+n(x.amount),0))]);if(name==='vendas')cards.push(['Pedidos',state.data.sales.length],['Venda bruta',money(state.data.sales.reduce((s,x)=>s+n(x.gross_amount),0))],['A receber',money(state.data.sales.filter(x=>['pending','partial'].includes(x.payment_status)).reduce((s,x)=>s+n(x.net_amount),0))]);if(name==='financeiro')cards.push(['Caixa disponível',$('mCash').textContent],['A receber',$('mReceive').textContent],['Despesas pendentes',money(state.data.expenses.filter(x=>x.status==='pending').reduce((s,x)=>s+n(x.amount),0)+state.data.financial_transactions.filter(x=>x.type==='expense'&&x.status==='pending').reduce((s,x)=>s+n(x.amount),0))]);$('pageSummary').innerHTML=cards.map(([a,b])=>`<div class="summary-card"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('');}
  function rowAction(view,row){if(state.role==='admin'&&row.user_id!==state.user.id)return '';if(view==='despesas'){const controls=[`<button class="row-action" data-edit="despesas" data-id="${esc(row.id)}">Editar</button>`,`<button class="row-action danger-action" data-expense-delete data-id="${esc(row.id)}">Excluir</button>`];if(isCreditCard(row.payment_method)&&row.status==='pending')controls.unshift(`<button class="row-action" data-card-paid="business" data-id="${esc(row.id)}">Marcar fatura paga</button>`);return `<div class="personal-actions">${controls.join('')}</div>`;}if(['produtos','fornecedores','marketing'].includes(view))return `<button class="row-action" data-edit="${view}" data-id="${esc(row.id)}">Editar</button>`;if(view==='compras'){const f=purchasePayment(row.id);return f?`<button class="row-action" data-payment="purchase" data-id="${esc(f.id)}">Pagamento</button>`:'';}if(view==='vendas')return `<button class="row-action" data-payment="sale" data-id="${esc(row.id)}">Recebimento</button>`;return '';}
  function fillTable(view){const rows=tableRows(view),isFinance=view==='financeiro';const columns=isFinance?[['description','Descrição'],['date','Data'],['type','Tipo'],['status','Status'],['amount','Valor']]:views[view].cols;const filtered=state.search?rows.filter(x=>JSON.stringify(x).toLocaleLowerCase('pt-BR').includes(state.search.toLocaleLowerCase('pt-BR'))):rows;$('tableBody').innerHTML=filtered.map(row=>`<tr>${columns.map(([key])=>`<td>${isFinance?(key==='date'?dateLabel(row.date):key==='amount'?`<span class="${row.positive?'positive':'negative'}">${row.positive?'+':'−'} ${money(row.amount)}</span>`:key==='status'?`<span class="status">${esc(row.status)}</span>`:esc(row[key])):val(view,key,row)}</td>`).join('')}<td>${rowAction(view,row)}</td></tr>`).join('');$('tableEmpty').hidden=filtered.length>0;}
