  function renderPriceResult(calculate){const p=state.data.products.find(x=>x.id===$('priceProduct')?.value),el=$('priceResult');if(!p){el.innerHTML='<div class="eyebrow">SIMULAÇÃO</div><h2>Cadastre um produto</h2><p>Adicione produtos e custos para calcular um preço.</p>';return;}if(!calculate){el.innerHTML=`<div class="eyebrow">SIMULAÇÃO</div><h2>${esc(p.name)}</h2><p>Custo médio registrado: ${money(p.purchase_cost)} por unidade. Selecione o canal e calcule sua margem.</p>`;return;}const f=feeFor($('priceChannel').value),margin=n($('marginTarget').value)/100,rate=(n(f.commission_percent)+n(f.ads_percent))/100,denom=1-rate-margin,price=denom>0?(n(p.purchase_cost)+n(f.fixed_fee)+n(f.seller_shipping))/denom:0,fees=price*rate+n(f.fixed_fee)+n(f.seller_shipping),profit=price-fees-n(p.purchase_cost);el.innerHTML=`<div class="eyebrow">PREÇO SUGERIDO · ${esc(labels[$('priceChannel').value]||$('priceChannel').value)}</div><h2>${money(price)}</h2><p>Margem alvo de ${Math.round(margin*100)}% por unidade.</p><div class="price-breakdown"><span>Custo do produto</span><strong>${money(p.purchase_cost)}</strong><span>Taxas e frete estimados</span><strong>${money(fees)}</strong><span>Lucro estimado</span><strong>${money(profit)}</strong></div>`;}
  function fieldHtml(field,initial={}){const[key,label,type='text',extra]=field,id=`field-${key}`,value=initial[key]??(type==='date'?today():type==='number'?0:'');let input='';if(type==='select'){input=`<select id="${id}" name="${key}" ${field[3]===true?'required':''}>${extra.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>`;}else if(type==='product'||type==='supplier'){const list=(type==='product'?state.data.products:state.data.suppliers).filter(x=>x.user_id===state.user.id);input=`<select id="${id}" name="${key}" ${field[3]===true?'required':''}><option value="">Selecione…</option>${list.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`;}else if(type==='textarea')input=`<textarea id="${id}" name="${key}" rows="3">${esc(value)}</textarea>`;else{const integer=['quantity','min_stock'].includes(key);input=`<input id="${id}" name="${key}" type="${type}" value="${esc(value)}" ${field[3]===true?'required':''} ${type==='number'?`min="${key==='quantity'?1:0}" step="${integer?'1':'0.01'}"`:''}>`;}return `<div class="field"><label for="${id}">${esc(label)}</label>${input}</div>`;}
  function openRecord(action,channel){const map={'add-product':'produtos','add-supplier':'fornecedores','add-purchase':'compras','new-sale':'vendas','add-expense':'despesas','add-campaign':'marketing','add-adjustment':'financeiro','adjust-stock':'ajuste'};const name=map[action];if(!name)return;if(['compras','vendas','ajuste'].includes(name)&&!state.data.products.length){toast('Cadastre um produto antes de registrar entrada ou saída de estoque.');showView('produtos');return;}state.editing={name,id:null};const def=views[name];const fields=name==='ajuste'?[['product_id','Produto','product',true],['direction','Tipo de ajuste','select',[['in','Entrada manual'],['out','Saída manual']]],['quantity','Quantidade','number',true],['notes','Motivo','textarea',true]]:def?.fields||[['type','Tipo','select',[['income','Entrada'],['expense','Saída']]],['description','Descrição','text',true],['category','Categoria','text'],['amount','Valor (R$)','number',true],['transaction_date','Data','date'],['status','Status','select',[['paid','Pago/recebido'],['pending','Pendente']]],['payment_method','Forma de pagamento','text'],['notes','Observações','textarea']];$('dialogTitle').textContent=def?.addLabel?.replace(/^＋\s*/,'')|| (name==='ajuste'?'Ajustar estoque':'Ajuste de caixa');$('formFields').innerHTML=fields.map(f=>fieldHtml(f)).join('');if(channel&&$('field-channel'))$('field-channel').value=channel;if(name==='compras')$('field-payment_status').value='pending';if(name==='vendas')$('field-payment_status').value='pending';$('recordDialog').showModal();}
